const prev = $('Google Drive - Baixar arquivo JSON').item;
const fileMeta = $('Filtrar apenas arquivos JSON').item.json;
const dbMeta = $input.item.json || {};

let rawStr = '';
let content = null;

if (prev.binary && prev.binary.data) {
  const buf = Buffer.from(prev.binary.data.data, 'base64');
  rawStr = buf.toString('utf-8');
  try { content = JSON.parse(rawStr); } catch (e) {}
} else if (typeof prev.json === 'object') {
  content = prev.json;
  rawStr = JSON.stringify(content);
}

if (!content) {
  return { json: { should_skip: true, reason: 'empty_or_invalid_json', fileName: fileMeta.name } };
}

const crypto = require('crypto');
const downloadedHash = crypto.createHash('sha256').update(rawStr).digest('hex');
const dbHash = String(dbMeta.content_hash || '');
const vectorCount = parseInt(dbMeta.vector_count || 0, 10);

// PROTECAO CONTRA DUPLICACAO:
// Se o hash do arquivo no GDrive for identico ao hash no Postgres e ja possuir vetores (>0), PULA!
if (dbHash && dbHash === downloadedHash && vectorCount > 0) {
  return {
    json: {
      should_skip: true,
      fileName: fileMeta.name,
      fileId: fileMeta.id,
      reason: 'hash_identical_no_change',
      vectorCount
    }
  };
}

const fileName = fileMeta.name;
const fileId = fileMeta.id;
const firstItem = Array.isArray(content) ? content[0] : content;
const categoria = firstItem.categoria || 'geral';
const titulo = firstItem.titulo || fileName;
const rawJsonSql = JSON.stringify(content).replace(/'/g, "''");

return {
  json: {
    should_skip: false,
    fileName,
    fileId,
    categoria,
    titulo,
    contentHash: downloadedHash,
    rawJsonSql,
    content
  }
};

function toNaturalText(val, indent = 0) {
  const prefix = "  ".repeat(indent);
  if (typeof val === 'string') return prefix + val.trim();
  if (typeof val === 'number' || typeof val === 'boolean') return prefix + String(val);
  if (val && typeof val === 'object' && !Array.isArray(val)) {
    const lines = [];
    if (val.description) lines.push(prefix + String(val.description).trim());
    for (const [k, v] of Object.entries(val)) {
      if (['description', 'type', '$schema'].includes(k.toLowerCase())) continue;
      const kClean = k.replace(/_/g, ' ').trim();
      const capKey = kClean.charAt(0).toUpperCase() + kClean.slice(1);
      if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
        lines.push(`${prefix}• ${capKey}: ${v}`);
      } else {
        lines.push(`${prefix}• ${capKey}:`);
        const sub = toNaturalText(v, indent + 1);
        if (sub) lines.push(sub);
      }
    }
    return lines.join('\n');
  }
  if (Array.isArray(val)) {
    const lines = [];
    for (const item of val) {
      if (typeof item === 'string' || typeof item === 'number' || typeof item === 'boolean') {
        lines.push(`${prefix}• ${item}`);
      } else {
        const sub = toNaturalText(item, indent + 1);
        if (sub) {
          lines.push(`${prefix}•`);
          lines.push(sub);
        }
      }
    }
    return lines.join('\n');
  }
  return '';
}

const docInfo = $('Code - Verificar Mudanca e Hash').item.json;
const activeModel = $('Postgres - Obter Modelo Ativo do RAG').item.json.active_model || 'qwen3-embedding:0.6b';
const content = docInfo.content;
const fileName = docInfo.fileName;
const fileId = docInfo.fileId;
const categoria = docInfo.categoria;
const titulo = docInfo.titulo;
const fonte = content.fonte || 'Fatec Bebedouro';
const resumo = content.resumo || '';

const chunks = [];
let chunkIdx = 0;

if (resumo) {
  const headerText = `DOCUMENTO: ${titulo}\nCATEGORIA: ${categoria}\nFONTE: ${fonte}\n\nRESUMO INSTITUCIONAL:\n${resumo}`;
  chunks.push({
    fileName,
    fileId,
    activeModel,
    chunkIndex: chunkIdx++,
    chunkType: 'resumo',
    chunkText: headerText,
    metadata: {
      file: fileName,
      file_name: fileName,
      file_id: fileId,
      source: fileName,
      categoria,
      titulo,
      fonte,
      chunk_index: chunkIdx - 1,
      chunk_type: 'resumo',
      model: activeModel
    }
  });
}

if (content.dados_estruturados && typeof content.dados_estruturados === 'object') {
  for (const [secao, dados] of Object.entries(content.dados_estruturados)) {
    const textoSecao = toNaturalText(dados);
    if (!textoSecao) continue;
    const chunkText = `DOCUMENTO: ${titulo}\nTÓPICO / SEÇÃO: ${secao}\nFONTE: ${fonte}\n\nINFORMAÇÕES OFICIAIS:\n${textoSecao}`;
    chunks.push({
      fileName,
      fileId,
      activeModel,
      chunkIndex: chunkIdx++,
      chunkType: 'secao_' + secao,
      chunkText,
      metadata: {
        file: fileName,
        file_name: fileName,
        file_id: fileId,
        source: fileName,
        categoria,
        titulo,
        fonte,
        secao,
        chunk_index: chunkIdx - 1,
        chunk_type: 'secao',
        model: activeModel
      }
    });
  }
}

for (const extraKey of ['Informações Adicionais', 'estagio', 'total_de_aulas', 'fonte_detalhe_eixos']) {
  if (content[extraKey]) {
    const textoExtra = toNaturalText(content[extraKey]);
    if (!textoExtra) continue;
    const chunkText = `DOCUMENTO: ${titulo}\nTÓPICO / SEÇÃO: ${extraKey}\nFONTE: ${fonte}\n\nINFORMAÇÕES OFICIAIS:\n${textoExtra}`;
    chunks.push({
      fileName,
      fileId,
      activeModel,
      chunkIndex: chunkIdx++,
      chunkType: 'extra_' + extraKey,
      chunkText,
      metadata: {
        file: fileName,
        file_name: fileName,
        file_id: fileId,
        source: fileName,
        categoria,
        titulo,
        fonte,
        secao: extraKey,
        chunk_index: chunkIdx - 1,
        chunk_type: 'extra',
        model: activeModel
      }
    });
  }
}

if (Array.isArray(content.perguntas_frequentes)) {
  for (const faq of content.perguntas_frequentes) {
    const pergunta = faq.pergunta || '';
    const resposta = faq.resposta || '';
    const tags = Array.isArray(faq.palavras_chave) ? faq.palavras_chave.join(', ') : '';
    const chunkText = `DOCUMENTO: ${titulo}\nCATEGORIA: ${categoria}\nPERGUNTA FREQUENTE: ${pergunta}\nRESPOSTA OFICIAL: ${resposta}${tags ? '\nPALAVRAS-CHAVE: ' + tags : ''}`;
    chunks.push({
      fileName,
      fileId,
      activeModel,
      chunkIndex: chunkIdx++,
      chunkType: 'faq',
      chunkText,
      metadata: {
        file: fileName,
        file_name: fileName,
        file_id: fileId,
        source: fileName,
        categoria,
        titulo,
        fonte,
        pergunta,
        chunk_index: chunkIdx - 1,
        chunk_type: 'faq',
        model: activeModel
      }
    });
  }
}

return chunks.map(c => ({ json: c }));

const chunk = $('Fatiar JSON em Chunks (FAQ e Docs)').item.json;
const embRes = $json;
const embedding = embRes.embedding || [];

const sanitize = (txt) => String(txt || '').replace(/'/g, "''");
const metadataJson = sanitize(JSON.stringify(chunk.metadata));
const chunkTextSql = sanitize(chunk.chunkText);
const vectorStr = '[' + embedding.join(',') + ']';

const sql = `INSERT INTO fatec_rag_vectors_poc (text, metadata, document, cmetadata, embedding) VALUES ('${chunkTextSql}', '${metadataJson}'::jsonb, '${chunkTextSql}', '${metadataJson}'::jsonb, '${vectorStr}'::vector);`;

return {
  json: {
    insert_sql: sql,
    fileName: chunk.fileName,
    chunkIndex: chunk.chunkIndex,
    dim: embedding.length
  }
};
